1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: QuoteStep[];
16	};
17	
18	export type ScenarioResult = {
19	  results: unknown[];
20	};
21	
22	const PROCESSING_FEE = 5;
23	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
24	
25	const BASE_PREMIUMS: Record<string, number> = {
26	  sword: 100,
27	  amulet: 60,
28	  staff: 80,
29	  potion: 40,
30	  rune: 25,
31	  moonstone: 25,
32	};
33	
34	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
35	
36	const BLOCK_SIZE = 3;
37	const BLOCK_BASE_PREMIUM = 60;
38	
39	const alikeItemGroups = (items: Item[]): Item[][] => {
40	  const groupsByType = new Map<string, Item[]>();
41	
42	  for (const item of items) {
43	    const group = groupsByType.get(item.type) ?? [];
44	    group.push(item);
45	    groupsByType.set(item.type, group);
46	  }
47	
48	  return [...groupsByType.values()];
49	};
50	
51	const basePremiumOfGroup = (group: Item[]): number =>
52	  group.length === BLOCK_SIZE
53	    ? BLOCK_BASE_PREMIUM
54	    : group.reduce((total, item) => total + basePremiumOf(item), 0);
55	
56	const totalBasePremiumOf = (items: Item[]): number =>
57	  alikeItemGroups(items).reduce(
58	    (total, group) => total + basePremiumOfGroup(group),
59	    0,
60	  );
61	
62	const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
63	
64	type ItemSurchargeRule = {
65	  appliesTo: (item: Item) => boolean;
66	  rate: number;
67	};
68	
69	const CURSE_SURCHARGE_RATE = 0.5;
70	const HIGH_ENCHANTMENT_THRESHOLD = 5;
71	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
72	
73	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
74	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
75	  {
76	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
77	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
78	  },
79	];
80	
81	const totalSurchargeRateOf = (item: Item): number =>
82	  ITEM_SURCHARGE_RULES.reduce(
83	    (rate, rule) => (rule.appliesTo(item) ? rate + rule.rate : rate),
84	    0,
85	  );
86	
87	const itemSurchargeOf = (item: Item): number =>
88	  basePremiumOf(item) * totalSurchargeRateOf(item);
89	
90	const totalItemSurchargeOf = (items: Item[]): number =>
91	  items.reduce((total, item) => total + itemSurchargeOf(item), 0);
92	
93	const quotePremium = (items: Item[]): number => {
94	  const basePremium = totalBasePremiumOf(items);
95	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
96	
97	  return roundedInMHPCOsFavour(
98	    basePremium +
99	      totalItemSurchargeOf(items) +
100	      firstInsuranceSurcharge +
101	      PROCESSING_FEE,
102	  );
103	};
104	
105	export const runScenario = (scenario: Scenario): ScenarioResult => ({
106	  results: scenario.steps.map((step) => ({
107	    premium: quotePremium(step.items),
108	  })),
109	});
