const alikeItemGroups = (items: Item[]): Item[][] => [
  ...items
    .reduce(
      (groupsByType, item) =>
        groupsByType.set(item.type, [
          ...(groupsByType.get(item.type) ?? []),
          item,
        ]),
      new Map<string, Item[]>(),
    )
    .values(),
];
